<?php
function enqueue_motor_brands_logo_css()
{
    wp_enqueue_style(
        'brands-logo-style',
        get_stylesheet_directory_uri() . '/widget-shortcodes/home/motor/css/brands-logo-list.css',
        array(),
        '1.0',
        'all'
    );
}

function display_motor_brands_list_shortcode()
{
    enqueue_motor_brands_logo_css();

    $sorted_brands = get_motor_brand_list_data('motorcycle_make');
    // Start the HTML output buffer
    ob_start();
?>

    <div class="brands-list">
        <?php if (!empty($sorted_brands) && !is_wp_error($sorted_brands)): ?>
            <?php foreach ($sorted_brands as $brand): ?>
                <div style="display: flex; flex-direction: column; align-items: center;">
                    <a href="<?php echo esc_url(home_url('/motor/' . $brand['slug'])); ?>" class="brand-link">

                        <img src="<?php echo esc_url($brand['image_url']); ?>" alt="<?php echo esc_attr($brand['brand']); ?>" class="brand-logo" />
                    </a>
                    <span class="logo-brand-item"><?php echo esc_html($brand['brand']); ?></span>
                </div>

            <?php endforeach; ?>
        <?php endif; ?>
        <a href="/motorcycles">
            <div style="display: flex; flex-direction: column; align-items: center;">

                <img src="data:image/svg+xml;base64," class="brand-logo" />
                <span class="logo-brand-item">เพิ่มเติม</span>
            </div>

        </a>

    </div>
<?php
    // Return the buffer content as a string
    return ob_get_clean();
}
// Register the shortcode
add_shortcode('motor_brands_list', 'display_motor_brands_list_shortcode');
